head.script:
//

        tailwind.config = {
            darkMode: 'class',
            theme: {
                extend: {
                    colors: {
                        netflixRed: '#E50914',
                        netflixDark: '#08080C',
                        nexflixRed: '#E50914',
                    },
                    fontFamily: {
                        sans: ['Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif],
                        nexflix: ['"Bebas Neue"', 'Impact', 'Arial Black', 'sans-serif'],
                    },
                    animation: {
                        'fade-in-up': 'fadeInUp 0.8s ease-out forwards',
                        'pop': 'pop 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards',
                        'slow-zoom': 'slowZoom 30s ease-in-out alternate infinite',
                        'slide-down': 'slideDown 0.5s cubic-bezier(0.16, 1, 0.3, 1) forwards',
                        'spin-slow': 'spin 4s linear infinite'
                    },
                    keyframes: {
                        fadeInUp: {
                            '0%': { opacity: '0', transform: 'translateY(20px)' },
                            '100%': { opacity: '1', transform: 'translateY(0)' }
                        },
                        pop: {
                            '0%': { transform: 'scale(1)' },
                            '50%': { transform: 'scale(1.15)' },
                            '100%': { transform: 'scale(1)' }
                        },
                        slowZoom: {
                            '0%': { transform: 'scale(1)' },
                            '100%': { transform: 'scale(1.15)' }
                        },
                        slideDown: {
                            '0%': { transform: 'translateY(-100%)', opacity: '0' },
                            '100%': { transform: 'translateY(0)', opacity: '1' }
                        }
                    }
                }
            }
        }

//

//

window.goToCategory = function(genreName) {
            const el = document.getElementById('row-' + genreName.replace(/[^a-zA-Z0-9]/g, '-'));
            if(el) {
                el.scrollIntoView({behavior: 'smooth', block: 'center'});
            } else {
                window.location.hash = '#movies';
            }
        };

        window.showSeason = function(seasonNum) {
            document.querySelectorAll('.season-container').forEach(el => el.classList.add('hidden'));
            const target = document.getElementById('season-container-' + seasonNum);
            if(target) target.classList.remove('hidden');
        };

        window.switchWatchSeason = function(seasonNum) {
            document.querySelectorAll('.season-container').forEach(el => el.classList.add('hidden'));
            const target = document.getElementById('season-container-' + seasonNum);
            if(target) {
                target.classList.remove('hidden');
                target.classList.add('animate-fade-in');
            }
            document.querySelectorAll('.watch-season-tab').forEach(tab => {
                tab.classList.remove('bg-netflixRed', 'text-white', 'shadow-lg', 'shadow-netflixRed/30');
                tab.classList.add('text-gray-400');
            });
            const activeTab = document.getElementById('season-tab-' + seasonNum);
            if (activeTab) {
                activeTab.classList.add('bg-netflixRed', 'text-white', 'shadow-lg', 'shadow-netflixRed/30');
                activeTab.classList.remove('text-gray-400');
            }
        };

        window.toggleEpisodeView = function(mode) {
            const listBtn = document.getElementById('btn-ep-view-list');
            const gridBtn = document.getElementById('btn-ep-view-grid');
            if (mode === 'grid') {
                document.querySelectorAll('.episodes-list-mode').forEach(el => el.classList.add('hidden'));
                document.querySelectorAll('.episodes-grid-mode').forEach(el => el.classList.remove('hidden'));
                if (gridBtn) { gridBtn.classList.add('bg-white/15', 'text-white'); gridBtn.classList.remove('text-gray-400'); }
                if (listBtn) { listBtn.classList.remove('bg-white/15', 'text-white'); listBtn.classList.add('text-gray-400'); }
                try { localStorage.setItem('nexora_ep_view_mode', 'grid'); } catch(e) {}
            } else {
                document.querySelectorAll('.episodes-list-mode').forEach(el => el.classList.remove('hidden'));
                document.querySelectorAll('.episodes-grid-mode').forEach(el => el.classList.add('hidden'));
                if (listBtn) { listBtn.classList.add('bg-white/15', 'text-white'); listBtn.classList.remove('text-gray-400'); }
                if (gridBtn) { gridBtn.classList.remove('bg-white/15', 'text-white'); gridBtn.classList.add('text-gray-400'); }
                try { localStorage.setItem('nexora_ep_view_mode', 'list'); } catch(e) {}
            }
        };

        window.filterWatchEpisodes = function(query) {
            const q = (query || '').toLowerCase().trim();
            document.querySelectorAll('.episode-row-item, .episode-grid-item').forEach(item => {
                const text = (item.getAttribute('data-filter-text') || '').toLowerCase();
                if (!q || text.includes(q)) {
                    item.style.display = '';
                } else {
                    item.style.display = 'none';
                }
            });
        };


        window.sortSeasons = function(order) {
            const selector = document.getElementById('season-selector');
            if(!selector) return;
            const options = Array.from(selector.options);
            options.sort((a, b) => {
                const valA = parseInt(a.value);
                const valB = parseInt(b.value);
                return order === 'asc' ? valA - valB : valB - valA;
            });
            selector.innerHTML = '';
            options.forEach(opt => selector.appendChild(opt));

            // Re-select the first one and show it
            if(options.length > 0) {
                selector.value = options[0].value;
                showSeason(options[0].value);
            }
        };



//

//

        (function() {
            // Check for touch / iOS devices
            const isTouch = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
            if (isTouch) {
                document.documentElement.classList.add('touch-device');
            }
        })();

