            `,e.innerHTML=t};window.showManageProfilesModal=function(){const e=document.getElementById("manage-profiles-modal"),s=document.getElementById("manage-profiles-content");e.classList.remove("hidden"),e.classList.add("flex"),e.offsetWidth,e.classList.remove("opacity-0"),e.classList.add("opacity-100"),s.classList.remove("scale-95"),s.classList.add("scale-100"),window.renderProfilesList()};window.closeManageProfilesModal=function(){const e=document.getElementById("manage-profiles-modal"),s=document.getElementById("manage-profiles-content");e.classList.remove("opacity-100"),e.classList.add("opacity-0"),s.classList.remove("scale-100"),s.classList.add("scale-95"),setTimeout(()=>{e.classList.add("hidden"),e.classList.remove("flex"),window.renderWhoIsWatching()},300)};window.openAddProfileForm=function(){const e=document.getElementById("auth-modal"),s=document.getElementById("auth-content");e.classList.remove("hidden"),e.classList.add("flex"),e.offsetWidth,e.classList.remove("opacity-0"),e.classList.add("opacity-100"),s.classList.remove("scale-95"),s.classList.add("scale-100"),switchAuthTab("register")};window.closeAuthModal=function(){const e=document.getElementById("auth-modal"),s=document.getElementById("auth-content");e.classList.remove("opacity-100"),e.classList.add("opacity-0"),s.classList.remove("scale-100"),s.classList.add("scale-95"),setTimeout(()=>{e.classList.add("hidden"),e.classList.remove("flex")},300)};window.switchAuthTab=function(e){const s=document.getElementById("tab-login"),t=document.getElementById("tab-register"),o=document.getElementById("form-login"),n=document.getElementById("form-register");e==="login"?(s.classList.add("text-white","border-netflixRed"),s.classList.remove("text-gray-500","border-transparent"),t.classList.add("text-gray-500","border-transparent"),t.classList.remove("text-white","border-netflixRed"),o.classList.remove("hidden"),n.classList.add("hidden")):(t.classList.add("text-white","border-netflixRed"),t.classList.remove("