body.script:
//

        window.dismissSplash = function() {
            const el = document.getElementById('netflix-intro-overlay');
            if (el && !el._dismissed) {
                el._dismissed = true;
                el.style.opacity = '0';
                el.style.pointerEvents = 'none';
                setTimeout(() => { if (el && el.parentNode) el.remove(); }, 200);
            }
        };
        setTimeout(window.dismissSplash, 700);

//

//

        window.renderMobileProfileSwitcher = async="async" function() {
            const container = document.getElementById('mobile-profile-switcher-list');
            if (!container) return;
            try {
                const profiles = (window.loadProfilesFromDB ? await window.loadProfilesFromDB() : []) || [];
                const currentName = localStorage.getItem('nexora_profile_name') || 'The Boss';
                let html = '';
                profiles.forEach(p => {
                    const img = p.image || 'https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=150&q=80';
                    const isActive = p.name === currentName;
                    const safeName = p.name.replace(/'/g, "\\'");
                    html += `
                        <div onclick="window.switchProfileFast('${safeName}', '${img}')" class="flex flex-col items-center gap-1 cursor-pointer flex-shrink-0 group">
                            <div class="w-12 h-12 rounded-xl overflow-hidden relative border-2 ${isActive ? 'border-netflixRed ring-2 ring-red-500/50 scale-105' : 'border-white/20 hover:border-white/60'} transition-all shadow-md">
                                <img src="${img}" class="w-full h-full object-cover" />
                                ${isActive ? '<div class="absolute bottom-0 inset-x-0 bg-red-600 text-[8px] font-black text-center text-white leading-tight">ACTIVE</div>' : ''}
                            </div>
                            <span class="text-[11px] ${isActive ? 'text-white font-bold' : 'text-gray-400 group-hover:text-gray-200'} truncate max-w-[60px] text-center">${p.name}</span>
                        </div>
                    `;
                });
                html += `
                    <div onclick="window.closeMobileProfileMenu(); window.openAddProfileForm();" class="flex flex-col items-center gap-1 cursor-pointer flex-shrink-0 group">
                        <div class="w-12 h-12 rounded-xl border-2 border-dashed border-white/30 hover:border-white flex items-center justify-center text-gray-400 group-hover:text-white transition-all bg-white/5">
                            <i class="fas fa-plus text-sm"></i>
                        </div>
                        <span class="text-[11px] text-gray-400 group-hover:text-white">Add</span>
                    </div>
                `;
                container.innerHTML = html;
            } catch(e) {
                console.error("Error loading profiles for mobile menu", e);
            }
        };

        window.switchProfileFast = function(name, img) {
            localStorage.setItem('nexora_profile_name', name);
            localStorage.setItem('nexora_profile_img', img);
            localStorage.setItem('nexora_user_loggedIn', 'true');
            if (window.updateProfileUI) window.updateProfileUI();
            if (window.showToast) window.showToast('Profile switched to ' + name);
            window.closeMobileProfileMenu();
            if (window.handleRoute) window.handleRoute();
        };

        window.openMobileProfileMenu = function() {
            const modal = document.getElementById('mobile-profile-modal');
            if (!modal) return;
            modal.classList.remove('hidden');
            modal.classList.add('flex');
            void modal.offsetWidth;
            modal.classList.remove('opacity-0');
            modal.classList.add('opacity-100');
            const drawer = modal.firstElementChild;
            if (drawer) {
                drawer.classList.remove('translate-y-full');
                drawer.classList.add('translate-y-0');
            }
            if (window.renderMobileProfileSwitcher) {
                window.renderMobileProfileSwitcher();
            }
        };

        window.closeMobileProfileMenu = function() {
            const modal = document.getElementById('mobile-profile-modal');
            if (!modal) return;
            modal.classList.remove('opacity-100');
            modal.classList.add('opacity-0');
            const drawer = modal.firstElementChild;
            if (drawer) {
                drawer.classList.remove('translate-y-0');
                drawer.classList.add('translate-y-full');
            }
            setTimeout(() => {
                modal.classList.add('hidden');
                modal.classList.remove('flex');
            }, 300);
        };

//

//

        (function() {
            let targetX = 0, targetY = 0, currentX = 0, currentY = 0, rafId = null;
            const bg = document.getElementById('dynamic-ambient-bg');
            if (!bg) return;

            function animateParallax() {
                currentX += (targetX - currentX) * 0.05;
                currentY += (targetY - currentY) * 0.05;
                bg.style.transform = `translate3d(${currentX.toFixed(2)}px, ${currentY.toFixed(2)}px, 0)`;
                if (Math.abs(targetX - currentX) > 0.08 || Math.abs(targetY - currentY) > 0.08) {
                    rafId = requestAnimationFrame(animateParallax);
                } else {
                    rafId = null;
                }
            }

            function requestMove(x, y, maxOffset) {
                targetX = (x / window.innerWidth - 0.5) * maxOffset;
                targetY = (y / window.innerHeight - 0.5) * maxOffset;
                if (!rafId) rafId = requestAnimationFrame(animateParallax);
            }

            const isTouchDevice = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
            if (!isTouchDevice) {
                window.addEventListener('mousemove', (e) => requestMove(e.clientX, e.clientY, 18), { passive: true });
            }
        })();

//
